const CHAP = ['ONE', 'TWO', 'THREE', 'FOUR', 'FIVE'];
try { window.DAILY && window.DAILY.then((D) => { if (D && D.murmur) SCENES[1].q = D.murmur; }); } catch (e) { }          /* (the Daily Frequency: today's Murmur message) */
