const FN_ORDER = ['lucid', 'hollow', 'drift', 'deep', 'embrace', 'velocity', 'haze', 'fold'];
function fieldNote() { let i = 0; try { i = (parseInt(localStorage.getItem('dl_fieldnote'), 10) || 0) % FN_ORDER.length; } catch (e) { } const cp = FN_ORDER[i], P = PANTRY[cp] || PANTRY.lucid;
  const c1 = P.does.split(/[;:]/)[0].trim(), q = cp === 'lucid' ? '4R-Hydroxytheanine: tracers almost double, the world warps.' : P.name + ': ' + c1.charAt(0).toLowerCase() + c1.slice(1) + '.';
  const col = '#' + P.c.map((v) => Math.round(v * 255).toString(16).padStart(2, '0')).join('');
  return { i, cp, q, col, plant: P.plant }; }          /* each sky is a quick cut; the desert's golden sun comes back */
